          </p>
        </section>
      `;
    }

    function FormField(field) {
      const requiredLabel = field.required
        ? ' <span class="required-marker" aria-hidden="true">*</span><span class="sr-only"> required</span>'
        : " <span>(optional)</span>";
      const helperId = `${field.id}-helper`;
      const errorId = `${field.id}-error`;
      const describedBy = [field.helper ? helperId : null, errorId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${requiredLabel}</label>
          <input
            id="${field.id}"
            name="${field.name}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
