          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)
            ? ""
            : "Error: Enter a valid email address, such as name@example.com.";
        }
      },
      {
        id: "phone",
        name: "phone",
        label: "Phone number",
        type: "tel",
        autocomplete: "tel",
        required: false,
        helper: "Use 10 digits, or include your country code, such as +1 555 123 4567.",
        validate(value) {
          const trimmed = value.trim();
          if (!trimmed) {
            return "";
          }

          return /^\+?[0-9\s().-]{7,20}$/.test(trimmed)
            ? ""
            : "Error: Enter a phone number using digits, spaces, dashes, parentheses, and an optional leading plus sign.";
        }
      }
    ];

    function SupportHero() {
      return `
        <section aria-labelledby="support-heading">
          <p class="eyebrow">Support team</p>
          <h1 id="support-heading">How can we help?</h1>
          <p class="intro">
            Tell us how to reach you and our support specialists will follow up with clear next steps.
          </p>
        </section>
      `;
    }

    function FormField(field) {
      const requiredLabel = field.required
        ? ' <span class="required-marker" aria-hidden="true">*</span><span class="sr-only"> required</span>'
        : " <span>(optional)</span>";
      const helperId = `${field.id}-helper`;
      const errorId = `${field.id}-error`;
      const describedBy = [field.helper ? helperId : null, errorId].filter(Boolean).join(" ");

      return `
        <div class="form-field">
          <label for="${field.id}">${field.label}${requiredLabel}</label>
          <input
            id="${field.id}"
            name="${field.name}"
            type="${field.type}"
            autocomplete="${field.autocomplete}"
            ${field.required ? "required" : ""}
            aria-describedby="${describedBy}"
          >
          ${field.helper ? `<p class="helper-text" id="${helperId}">${field.helper}</p>` : ""}
          <p class="error-message" id="${errorId}"></p>
        </div>
      `;
    }

    function ContactForm() {
      return `
        <section class="contact-card" aria-labelledby="form-heading">
          <div class="form-header">
            <h2 id="form-heading">Contact support</h2>
            <p>Fields marked with <span class="required-marker" aria-hidden="true">*</span> are required.</p>
          </div>
          <form id="support-form" novalidate>
            ${fields.map(FormField).join("")}
            <p class="status-message" role="status" id="form-status"></p>
            <button type="submit">Send request</button>
          </form>
        </section>
      `;
    }

    function SupportPage() {
      return `
        <div class="support-layout">
          ${SupportHero()}
          ${ContactForm()}
        </div>
      `;
    }

    function setFieldError(input, message) {
      const error = document.getElementById(`${input.id}-error`);
      if (message) {
        input.setAttribute("aria-invalid", "true");
        error.textContent = message;
      } else {
        input.removeAttribute("aria-invalid");
        error.textContent = "";
      }
    }

    function validateField(field) {
      const input = document.getElementById(field.id);
      const error = field.validate(input.value);
      setFieldError(input, error);
      return { input, error };
    }

    function setupValidation() {
      const form = document.getElementById("support-form");
      const status = document.getElementById("form-status");

      fields.forEach((field) => {
        const input = document.getElementById(field.id);
        input.addEventListener("blur", () => validateField(field));
        input.addEventListener("input", () => {
          if (input.getAttribute("aria-invalid") === "true") {
            validateField(field);
          }
          status.textContent = "";
        });
      });

      form.addEventListener("submit", (event) => {
        event.preventDefault();
        status.textContent = "";

        const results = fields.map(validateField);
        const firstInvalid = results.find((result) => result.error);

        if (firstInvalid) {
          firstInvalid.input.focus();
          return;
        }

        form.reset();
        fields.forEach((field) => setFieldError(document.getElementById(field.id), ""));
        status.textContent = "Your support request is ready to send.";
      });
    }

    document.getElementById("app").innerHTML = SupportPage();
    setupValidation();
  </script>
</body>
